using System;
using System.Diagnostics;
using System.IO.Compression;
using System.Text;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.ResponseCompression;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.DependencyInjection;

namespace PerformanceOptimizationDemo
{
    // 内存缓存服务
    public class CachedProductService
    {
        private readonly IMemoryCache _cache;
        private readonly IProductRepository _repository;

        public CachedProductService(IMemoryCache cache, IProductRepository repository)
        {
            _cache = cache;
            _repository = repository;
        }

        public async Task<Product> GetProductAsync(int id)
        {
            var cacheKey = $"product_{id}";

            return await _cache.GetOrCreateAsync(cacheKey, async entry =>
            {
                entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10);
                entry.SlidingExpiration = TimeSpan.FromMinutes(2);
                return await _repository.GetByIdAsync(id);
            });
        }

        public void InvalidateCache(int id)
        {
            _cache.Remove($"product_{id}");
        }
    }

    // 分布式缓存服务
    public class DistributedCacheService
    {
        private readonly IDistributedCache _cache;

        public DistributedCacheService(IDistributedCache cache)
        {
            _cache = cache;
        }

        public async Task<T> GetOrSetAsync<T>(string key, Func<Task<T>> factory,
            TimeSpan? expiration = null)
        {
            var cached = await _cache.GetStringAsync(key);
            if (cached != null)
            {
                return System.Text.Json.JsonSerializer.Deserialize<T>(cached);
            }

            var value = await factory();
            var json = System.Text.Json.JsonSerializer.Serialize(value);

            await _cache.SetStringAsync(key, json, new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = expiration ?? TimeSpan.FromHours(1)
            });

            return value;
        }
    }

    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public decimal Price { get; set; }
    }

    public interface IProductRepository
    {
        Task<Product> GetByIdAsync(int id);
    }

    // 最小 API 示例
    public static class MinimalApiExamples
    {
        public static WebApplication CreateMinimalApi()
        {
            var builder = WebApplication.CreateBuilder();

            // 配置服务
            builder.Services.AddMemoryCache();
            builder.Services.AddResponseCompression(options =>
            {
                options.EnableForHttps = true;
                options.Providers.Add<BrotliCompressionProvider>();
                options.Providers.Add<GzipCompressionProvider>();
            });

            var app = builder.Build();

            // 中间件
            app.UseResponseCompression();

            // 性能监控中间件
            app.Use(async (context, next) =>
            {
                var stopwatch = Stopwatch.StartNew();
                await next();
                stopwatch.Stop();

                context.Response.Headers.Add("X-Response-Time",
                    $"{stopwatch.ElapsedMilliseconds}ms");
            });

            // 最小 API 端点
            app.MapGet("/", () => "Hello World!");

            app.MapGet("/products/{id}", async (int id, IMemoryCache cache) =>
            {
                var cacheKey = $"product_{id}";
                var product = await cache.GetOrCreateAsync(cacheKey, async entry =>
                {
                    entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
                    return new Product { Id = id, Name = $"Product {id}", Price = 9.99m };
                });

                return Results.Ok(product);
            });

            app.MapPost("/products", async (Product product) =>
            {
                // 创建产品
                return Results.Created($"/products/{product.Id}", product);
            });

            // 带过滤器的端点
            app.MapGet("/admin", () => "Admin Area")
                .RequireAuthorization("AdminOnly");

            app.MapGet("/cached", () => "Cached Response")
                .CacheOutput(x => x.Expire(TimeSpan.FromMinutes(1)));

            return app;
        }
    }

    // 基准测试示例
    public class StringBenchmarks
    {
        public string ConcatString(int iterations)
        {
            var s = "";
            for (int i = 0; i < iterations; i++)
            {
                s += i.ToString();
            }
            return s;
        }

        public string UseStringBuilder(int iterations)
        {
            var sb = new StringBuilder();
            for (int i = 0; i < iterations; i++)
            {
                sb.Append(i);
            }
            return sb.ToString();
        }

        public string UseStringCreate(int iterations)
        {
            return string.Create(iterations.ToString().Length * iterations, iterations,
                (span, state) =>
                {
                    var index = 0;
                    for (int i = 0; i < state; i++)
                    {
                        var num = i.ToString();
                        num.AsSpan().CopyTo(span.Slice(index));
                        index += num.Length;
                    }
                });
        }
    }

    // 性能优化配置
    public static class PerformanceServiceCollectionExtensions
    {
        public static IServiceCollection AddPerformanceOptimizations(
            this IServiceCollection services)
        {
            // 内存缓存
            services.AddMemoryCache(options =>
            {
                options.SizeLimit = 1024;
            });

            // 响应压缩
            services.AddResponseCompression(options =>
            {
                options.EnableForHttps = true;
                options.Providers.Add<BrotliCompressionProvider>();
                options.Providers.Add<GzipCompressionProvider>();
                options.MimeTypes = ResponseCompressionDefaults.MimeTypes.Concat(
                    new[] { "application/json", "text/plain" });
            });

            // 配置 Brotli 压缩级别
            services.Configure<BrotliCompressionProviderOptions>(options =>
            {
                options.Level = CompressionLevel.Fastest;
            });

            return services;
        }
    }
}
